issue_context.body:
**Context:**
- Playwright Version: `@playwright/test@1.18.0-alpha-jan-12-2022`
- Operating System: macOS
- Node.js version: v14.17.6

**Code Snippet**

```ts
export const exampleTest = _test.extend<{ aNumber: number }>({
  aNumber: async ({}, use, testInfo) => {
    await use(10);
    console.log("use completed");
    await testInfo.attach("example.txt", {
      contentType: "text/plain",
      path: "/path/to/nowhere",
    });
    console.log("attach completed");
  },
});

exampleTest("foo", ({ aNumber }) => {
  expect(aNumber).toBe(10);
  console.log("done");
});
```

**Describe the bug**

The above code hangs when you run `npx playwright --reporter line`.  I expect it to error immediately. If there is an attachment that exists, I'd expect it to be included, but this case should at least error.

---

The above repro is a simplified example. I hit it when trying to add a per-test logger fixture which I want to add since we have too many `console.log`s spamming our test output (but who's output I don't want to lose).

Here's the fixture I was writing:

```ts
export const test = _test.extend<{
  logger: Logger;
  pollAPI: (id: string) => Promise<string>;
}>({
  logger: async ({}, use, testInfo) => {
    const outFile = testInfo.outputPath("test-logs.log");
    const transports: winston.transport[] = [
      new winston.transports.File({
        filename: outFile,
      }),
    ];

    // Force console output. This is sometimes nice to have locally.
    if (process.env["PLAYWRIGHT_TEST_FORCE_CONSOLE_LOGS"]) {
      transports.push(new winston.transports.Console());
    }

    const logger = winston.createLogger({
      level: "debug",
      transports,
    });

    const finished = new Promise((res, rej) => {
      logger.on("finish", res);
      logger.on("error", rej);
    });

    await use(logger);
    logger.end();
    await finished;
    await testInfo.attach("debug.log", {
      path: outFile,
      contentType: "text/plain",
    });
  },
  pollAPI: async ({ logger }, use) => {
    const pollAPI = async (id: string) => {
      logger.debug(`Polling for ${id}`);
      const cycles = Math.random() * 100;
      for (let i = 0; i < cycles; i++) {
        logger.debug(`still polling`);
      }
      logger.debug("finished polling");
      return "example";
    };
    await use(pollAPI);
  },
});

test("spam example", async () => {
  console.log("spams the console…");
});

test("per-test logging, without the spam!", async ({ pollAPI }) => {
  const result = await pollAPI("foo");
  expect(result).toBe("example");
});

```

